package practice;

import java.lang.annotation.ElementType;
import java.lang.annotation.Inherited;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;
import java.util.Optional;

/**
 * Tells the tracing agent how closely to trace the instances of a handler class.
 *
 * A handler is traced at the level its {@code @Traced} says. The annotation may sit on the
 * class, on any of its superclasses, or on any interface the class or a superclass implements,
 * directly or through another interface. One on the class or a superclass wins over one on an
 * interface. A class with none anywhere is not traced.
 */
public class TraceLookup {

    @Inherited
    @Retention(RetentionPolicy.RUNTIME)
    @Target(ElementType.TYPE)
    public @interface Traced {
        String level() default "SPANS";
    }

    /** The level {@code handler} is traced at, or empty when it isn't traced. */
    public Optional<String> levelOf(Class<?> handler) {
        Traced onClasses = handler.getAnnotation(Traced.class);
        if (onClasses != null) return Optional.of(onClasses.level());
        for (Class<?> c = handler; c != null; c = c.getSuperclass()) {
            Optional<String> found = fromInterfaces(c.getInterfaces());
            if (found.isPresent()) return found;
        }
        return Optional.empty();
    }

    /** The level on the first of {@code interfaces}, or on an interface they extend, that is traced. */
    Optional<String> fromInterfaces(Class<?>[] interfaces) {
        for (Class<?> i : interfaces) {
            Traced t = i.getAnnotation(Traced.class);
            if (t != null) return Optional.of(t.level());
            Optional<String> found = fromInterfaces(i.getInterfaces());
            if (found.isPresent()) return found;
        }
        return Optional.empty();
    }
}

package practice;

import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            TraceLookup lookup = new TraceLookup();
            System.out.println("OrderHandler: " + lookup.levelOf(OrderHandler.class));
            System.out.println("RefundHandler: " + lookup.levelOf(RefundHandler.class));
            System.out.println("ImportHandler: " + lookup.levelOf(ImportHandler.class));
            System.out.println("BatchImportHandler: " + lookup.levelOf(BatchImportHandler.class));
            System.out.println("SubImportHandler: " + lookup.levelOf(SubImportHandler.class));
            System.out.println("MetricsHandler: " + lookup.levelOf(MetricsHandler.class));
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }

    @TraceLookup.Traced(level = "FULL") interface Importer { }
    interface BatchImporter extends Importer { }
    interface Probe { }
    @TraceLookup.Traced(level = "SAMPLED") static class Handler { }
    static class OrderHandler extends Handler { }
    @TraceLookup.Traced(level = "OFF") static class RefundHandler extends Handler { }
    static class ImportHandler implements Probe, Importer { }
    static class BatchImportHandler implements BatchImporter { }
    static class SubImportHandler extends ImportHandler { }
    static class MetricsHandler implements Probe { }
}

